#include <stdio.h>
#include <stdint.h>
int main(int argc,char**argv){if(argc!=2)return 2;AVFormatContext*f=0;if(avformat_open_input(&f,argv[1],0,0)<0)return 3;avformat_find_stream_info(f,0);int i=av_find_best_stream(f,AVMEDIA_TYPE_VIDEO,-1,-1,0,0);AVCodecContext*c=avcodec_alloc_context3(avcodec_find_decoder(f->streams[i]->codecpar->codec_id));avcodec_parameters_to_context(c,f->streams[i]->codecpar);c->thread_count=1;if(avcodec_open2(c,c->codec,0)<0)return 4;AVPacket*p=av_packet_alloc();AVFrame*frame=av_frame_alloc();int count=0,with=0,nonidentity=0;printf("{\"frames\":[");while(1){int end=av_read_frame(f,p)<0;if(!end&&p->stream_index!=i){av_packet_unref(p);continue;}if(avcodec_send_packet(c,end?0:p)<0)return 5;av_packet_unref(p);while(avcodec_receive_frame(c,frame)>=0){AVFrameSideData*s=av_frame_get_side_data(frame,AV_FRAME_DATA_DOVI_METADATA);if(count)printf(",");printf("{\"pts\":%lld,\"metadata\":%s",(long long)frame->pts,s?"true":"false");if(s){with++;const AVDOVIMetadata*m=(void*)s->data;const AVDOVIRpuDataHeader*h=av_dovi_get_header(m);const AVDOVIDataMapping*d=av_dovi_get_mapping(m);int ident=1;printf(",\"denom\":%u,\"curves\":[",h->coef_log2_denom);for(int k=0;k<3;k++){if(k)printf(",");const AVDOVIReshapingCurve*q=&d->curves[k];printf("{\"pivots\":[");for(int a=0;a<q->num_pivots;a++)printf("%s%u",a?",":"",q->pivots[a]);printf("],\"pieces\":[");for(int a=0;a<q->num_pivots-1;a++){if(a)printf(",");printf("{\"method\":%d,\"order\":%d,\"poly\":[%lld,%lld,%lld]}",q->mapping_idc[a],q->poly_order[a],(long long)q->poly_coef[a][0],(long long)q->poly_coef[a][1],(long long)q->poly_coef[a][2]);if(q->mapping_idc[a]!=AV_DOVI_MAPPING_POLYNOMIAL||q->poly_coef[a][0]!=0||q->poly_coef[a][1]!=(1LL<<h->coef_log2_denom)||q->poly_coef[a][2]!=0)ident=0;}printf("]}");}printf("],\"identityPolynomial\":%s",ident?"true":"false");nonidentity+=!ident;}printf("}");count++;av_frame_unref(frame);}if(end)break;}printf("],\"count\":%d,\"withMetadata\":%d,\"nonIdentity\":%d}\n",count,with,nonidentity);av_frame_free(&frame);av_packet_free(&p);avcodec_free_context(&c);avformat_close_input(&f);return 0;}
